# coding: utf-8
import json
from pathlib import Path
from lesson_authoring import entry as E
B=[['拉丁 flos，词干 flor-','花']]
W=[
E('flower','英 /ˈflaʊə/；美 /ˈflaʊər/','花；开花；发展成熟','植物长到一定阶段，花开出来；人的才华也可以慢慢绽放。','经古法语 flor／盎格鲁法语 flur，来自拉丁 florem。英语名词转作动词。不能拆成 flow 流动 + -er。',B+[['古法语 flor → 中古英语 flour','花；也可比喻精华、盛期'],['英语 flower','花；开花、发展成熟']],'a flower 可以是一朵花，flowers 也常指送人的鲜花。作动词时，The plant flowers in June 是这种植物六月开花；才能、艺术等也可以 flower，强调渐渐充分展开。','a bunch of flowers；flowers in spring；talent flowers。','flower 与 flour 在常见英美口音中同音，但现在一个是花，一个是面粉。写句子时不能因读音相同就互换。',('She put the flowers in a glass vase.','她把鲜花插进玻璃花瓶。'),('These plants flower in early summer.','这些植物在初夏开花。'),('His talent flowered after he joined the orchestra.','加入乐团后，他的才华逐渐绽放。'),sources=['https://www.etymonline.com/word/flower']),
E('flour','英 /ˈflaʊə/；美 /ˈflaʊər/','面粉；谷物等磨成的粉；撒上面粉','从磨碎的谷物里取出细细的那部分，用它和面、烘焙。','原本与 flower 是同一个词，花可比喻最精华的部分，因而用来指磨碎谷物中的细粉。后来拼写分开，flour 固定表示粉，flower 表示花。',B+[['法语／早期英语 flor、flour／flower','花 → 精华、最细好的部分'],['英语 flour','细粉；后来也可作动词，撒面粉']],'flour 不只可以是小麦面粉，也可说 rice flour 米粉、almond flour 杏仁粉。说 a bag of flour，不用 a flour 来表示一袋；动词 flour the surface 是往台面撒粉。','wheat flour；rice flour；flour a work surface。','词源中的“精华”解释命名，不是营养评价，也不表示现代所有 flour 都是精制白面粉。flour 与 flower 的同音有真实历史背景。',('Add the flour and stir until smooth.','加入面粉，搅拌至顺滑。'),('Lightly flour the work surface before rolling out the dough.','擀面团前，在操作台上轻撒一层面粉。'),sources=['https://www.etymonline.com/word/flour','https://en.wiktionary.org/wiki/flour']),
E('flourish','英 /ˈflʌrɪʃ/；美 /ˈflɜːrɪʃ/','繁荣；茁壮成长；挥舞；引人注意的动作或装饰','花长得旺，引出事业蓬勃发展；花式展示，又引出潇洒一挥、装饰性的笔画。','经古法语 florir 的 floriss- 词干，来自拉丁 florere 开花、兴旺。英语名词由动词发展，-ish 不是“有点像”的普通形容词后缀。',B+[['拉丁 florere → 古法语 florir、floriss-','开花 → 兴旺'],['英语 flourish','蓬勃发展；又指显眼挥舞、装饰性动作']],'a business flourishes 是生意兴旺，不是只勉强活着。flourish a letter 是拿着信得意地挥动；with a flourish 则像表演最后潇洒一收，让人注意到这个动作。','flourish in a new environment；a flourishing business；with a flourish。','flourish 的读音不是 flour 后加 /ɪʃ/。它可以表示挥舞某物，但普通随手挥一下通常用 wave；flourish 更有展示意味。',('Small businesses flourished in the growing town.','随着小镇发展，小企业蓬勃兴起。'),('She flourished the winning ticket above her head.','她把中奖票举过头顶，得意地挥了挥。'),('He signed his name with a flourish.','他潇洒地一挥笔，签下了名字。'),sources=['https://www.etymonline.com/word/flourish']),
E('flourishing','英 /ˈflʌrɪʃɪŋ/；美 /ˈflɜːrɪʃɪŋ/','繁荣的；蓬勃发展的','已经长出了活力，而且势头很好：店铺忙起来，艺术活动也多起来。','flourish + -ing，既是现在分词，也作形容词；沿用开花、兴旺这条比喻。',B+[['拉丁 florere → 法语 florir → 英语 flourish','开花 → 兴旺'],['英语 flourish + -ing','正在兴旺；蓬勃发展的']],'a flourishing arts scene 指活跃、繁盛的艺术环境；a flourishing garden 指花园生长旺盛。它肯定的是发展状态，不保证没有困难，也不只指赚钱。','a flourishing industry；a flourishing community；a flourishing garden。','flourishing 比 growing 更强调长得好、有活力。a growing problem 虽然也在增长，却通常不会用 flourishing 来中性描述。',('The city has a flourishing independent music scene.','这座城市的独立音乐发展得很兴旺。'),('She turned the empty yard into a flourishing garden.','她把空院子变成了一座生机勃勃的花园。'),sources=['https://www.etymonline.com/word/flourishing']),
E('floral','英 /ˈflɔːrəl/；美 /ˈflɔːrəl/','花的；花卉图案的；花香的','衣服上印着花，香水闻起来像花，布置也用到了花。','经法语 floral 来自拉丁 floralis，与 flos 花相关。英语早期也用于花神 Flora，随后广泛表示与花有关。',B+[['拉丁 floralis → 法语 floral','花的、花神的'],['英语 floral','花卉的；花纹、花香的']],'a floral dress 是带花卉图案的裙子，不一定由真花做成；a floral scent 是花香；a floral arrangement 则可以是真花组成的插花布置。','a floral pattern；a floral scent；floral arrangements。','floral 常客观描述花、花纹、花香；flowery 用于语言时可能嫌它修饰太多。floral speech 不是表达“辞藻华丽”的常见说法。',('She chose a dress with a blue floral pattern.','她选了一条带蓝色花卉图案的裙子。'),('The tea has a delicate floral scent.','这款茶有一股淡淡的花香。'),sources=['https://www.etymonline.com/word/floral','https://en.wiktionary.org/wiki/floral']),
E('florist','英 /ˈflɒrɪst/；美 /ˈflɔːrɪst/','花商；花艺师；花店','把花挑选、搭配、包装成花束，并出售给需要的人。','以拉丁 flor- 花和表示从业者的 -ist 构词，受法语 fleuriste 影响；早期也指栽培、出售花卉的人。',B+[['法语 fleuriste 提供构词参照','从事花卉栽培、销售的人'],['英语 flor- + -ist → florist','花商、花艺师；也可指花店']],'常见 order flowers from a florist 向花店订花。英式 at the florist’s 往往指在花店；florist 可以指人，也可按场景指商店，不要每次都译成“花学家”。','a local florist；work as a florist；order from a florist。','botanist 是研究植物的植物学家，florist 的重点是花卉生意或花艺。两者都接触植物，职业职责却不同。',('The florist helped us choose flowers for the table.','花艺师帮我们挑选了摆在桌上的花。'),('I ordered a bouquet from a local florist.','我向附近一家花店订了一束花。'),sources=['https://www.etymonline.com/word/florist','https://en.wiktionary.org/wiki/florist']),
E('flora','英 /ˈflɔːrə/；美 /ˈflɔːrə/','某地区或时期的植物群；植物志','把一个地方生长的植物放在一起看：这里有哪些树、草和其他植物？','来自拉丁花神名 Flora，与 flos 花相关；后来用于植物书籍的标题，再用来统称一个地方或时代的植物。',B+[['拉丁 Flora','花神名'],['植物书籍标题 → 英语 flora','植物志；某地区或时期的植物群']],'the flora of an island 指岛上的植物总体，不只指颜色鲜艳的花。一本描述这些植物的书也可以叫 a flora。固定搭配 flora and fauna 是植物群与动物群。','native flora；local flora；flora and fauna。','flora 不是 flower 的普通复数；几朵花是 flowers。日常说植物群用 flora，谈一本地区植物志时才可能按可数书籍来用。',('The island has a rich native flora.','这个岛的本土植物种类丰富。'),('The book describes the flora of the mountain region.','这本书介绍了该山区的植物。'),sources=['https://www.etymonline.com/word/flora','https://en.wiktionary.org/wiki/flora']),
E('flowery','英 /ˈflaʊəri/；美 /ˈflaʊəri/','多花的；花香的；辞藻华丽的','花很多，装饰也很多；如果装饰堆在语言里，就是满篇漂亮词句。','英语 flower + 形容词后缀 -y，表示有花的、像花的。由花的装饰效果引申到语言。',B+[['古法语 flor → 英语 flower','花'],['flower + -y → flowery','花多、似花；语言过分装饰']],'a flowery meadow 是鲜花盛开的草地；flowery language 常暗示话说得太华丽、绕得太多，听者反而难抓重点。它不等于简单的“英文说得好”。','flowery language；a flowery description；a flowery meadow。','flowery 与 floury 常同音：前者与花有关，后者指带面粉的、像粉一样的。写作中不能把华丽语言拼成 floury language。',('We crossed a flowery meadow on the way home.','回家路上，我们穿过了一片开满花的草地。'),('Use clear wording instead of flowery language.','用清楚的措辞，不要堆砌华丽辞藻。'),sources=['https://en.wiktionary.org/wiki/flowery']),
E('florid','英 /ˈflɒrɪd/；美 /ˈflɔːrɪd/','过分华丽的；脸色红润或涨红的','像花开得浓艳一样：可以是装饰繁复，也可以是脸上红得很明显。','经法语 floride 来自拉丁 floridus，意为开花的、繁盛的。由花的浓艳发展出华丽与红润等用法。',B+[['拉丁 floridus → 法语 floride','开花的、繁盛的'],['英语 florid','装饰华丽；面色红润、涨红']],'florid prose 指修饰繁多的文章，常带批评语气；a florid face 指脸色明显发红。两个意思都可记住浓艳的画面，但遇到脸色不能译成“措辞华丽”。','florid prose；a florid style；a florid complexion。','floral 是花卉的，florid 是浓艳、繁饰或面色发红。a floral pattern 是花纹，a florid style 可能根本没有画花。',('The editor cut several paragraphs of florid prose.','编辑删掉了几段辞藻堆砌的文字。'),('He had a round, florid face.','他脸圆圆的，面色红润。'),sources=['https://www.etymonline.com/word/florid']),
E('floret','英 /ˈflɒrət/；美 /ˈflɔːrət/；也有 /fləˈret/','小花；花菜、西蓝花的一小簇','把一整颗西蓝花分开，得到一小簇一小簇像小树的部分。','与 flor- 花和表示小的 -et 有关；古法语 florete 是 flor 的指小形式。现代常用在植物学和菜谱里。',B+[['古法语 flor → florete','花 → 小花'],['英语 floret','小花；菜花的一小簇']],'菜谱中的 broccoli florets 是西蓝花的小簇，不是让你寻找已经盛开的花。植物学的 floret 可指聚在花序里的单朵小花；烹饪用法按食材分块来理解。','broccoli florets；cauliflower florets；cut into florets。','floret 不是 petal 花瓣。花瓣是花的一个组成部分，floret 可以是一朵小花，也可以是一簇食材。',('Cut the cauliflower into small florets.','把花菜切分成小朵。'),('Add the broccoli florets to the pan.','把西蓝花小朵放进锅里。'),sources=['https://www.etymonline.com/word/floret','https://www.oxfordlearnersdictionaries.com/definition/english/floret','https://en.wiktionary.org/wiki/floret']),
E('cauliflower','英 /ˈkɒlɪflaʊə/；美 /ˈkɑːlɪˌflaʊər/','花菜；菜花；花椰菜','菜市场里那种常见的白色、紧密成团的花菜，能分成一小朵一小朵。','早期英语 cole florye 与意大利“开花的甘蓝”名称有关；前半上溯拉丁 caulis 茎、甘蓝，后半为花。后来拼写前半向拉丁形式靠拢，后半受英语 flower 影响。',[['拉丁 caulis（茎、甘蓝）＋ flos／flor-（花）','两种成分共同参与命名'],['意大利相关菜名 → 英语 cole florye → cauliflower','开花的甘蓝 → 花菜']],'buy a cauliflower 可以指买一整颗，some cauliflower 则当食材说。cauliflower rice 是把花菜切成像米粒的小碎块，名称里有 rice，也不表示它真的含米。','roasted cauliflower；cauliflower florets；a head of cauliflower。','cauliflower 通常是白色花菜，broccoli 通常是绿色西蓝花；有其他颜色品种，但两个单词不是同一蔬菜的英美拼写差异。',('We roasted the cauliflower with olive oil.','我们加了橄榄油烤花菜。'),('She bought a cauliflower and a bag of carrots.','她买了一颗花菜和一袋胡萝卜。'),sources=['https://www.etymonline.com/word/cauliflower','https://en.wiktionary.org/wiki/cauliflower'])
]
ROOT=dict(id='C0435',meaning='花；开花、兴旺',core='FLOR = FLOWER / BLOOM',image='花从枝头开出来：可以看花的形状和香气，也可以把开花比喻成才华与事业兴旺。',intro='拉丁 flos 的词干是 flor-。经过法语等语言，英语留下 floral、florist 这样的清楚外形，也留下 flower、flour、flourish。拼写变了，花、精华、兴旺这些意义之间仍有可理解的联系。',forms='flor- 是拉丁花的词干；flower 是经法语借入的日常词。flour 由“花、精华”中的细粉义分出；flourish 经法语动词词干借入，不能简单拆为 flour 面粉加 -ish。',branches=[['花与花卉行业','flower、floral、florist、flora'],['开花般兴旺','flourish、flourishing'],['花式装饰与浓艳','flowery、florid'],['餐桌上的历史联系','flour、floret、cauliflower']],contrasts='floral 花卉的，flowery 语言华丽的，florid 装饰浓艳或面色红润的；flour 和 flower 常同音，但现代写法、意思已分开。',practice='The florist’s business flourished as more people bought flowers for their homes.\n\n越来越多人买花装点家里，这家花店的生意也越来越兴旺。',words=[x['word'] for x in W],exclude={})
if __name__=='__main__':
 for name,data in [('roots_flor',[ROOT]),('words_flor',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print(len(W),sum(len(x['examples']) for x in W))
